  route = excluded.route, source_name = excluded.source_name, source_url = excluded.source_url,
  source_license = excluded.source_license, review_status = 'approved', route_miles = excluded.route_miles, reviewed_at = now();

insert into public.trail_soil_profiles (trail_id, geometry_version, profile, confidence, usable_samples, research_location, source_name)
values ('wv-snowshoe', 1, '{"dominantSoil":"Silt Loam","secondarySoil":null,"naturalDrainage":"Poorly drained","soilDryingFactor":0.84,"textureFactor":0.9,"drainageFactor":0.72,"confidence":"Low","sampleCoverage":"1/17","soilLat":38.422782,"soilLon":-79.990415,"source":"USDA NRCS SSURGO via Soil Data Access","researchedAt":"2026-07-28T18:35:48.606Z","samplingMethod":"Center-area fallback; mapped route returned no usable SSURGO samples"}'::jsonb, 'Low', 1,
  ST_SetSRID(ST_MakePoint(-79.990415, 38.422782), 4326)::extensions.geography, 'USDA NRCS SSURGO')
on conflict (trail_id, geometry_version) do update set
  profile = excluded.profile, confidence = excluded.confidence, usable_samples = excluded.usable_samples,
  research_location = excluded.research_location, source_name = excluded.source_name, calculated_at = now();

commit;

select state_code, count(*) as active_trails
from public.trail_systems
where record_status = 'Active' and state_code in ('OH', 'WV')
group by state_code
order by state_code;

select t.id, t.name, t.region, t.geometry_version, r.route_miles, s.confidence, s.usable_samples
from public.trail_systems t
join public.trail_routes r on r.trail_id = t.id and r.geometry_version = t.geometry_version
join public.trail_soil_profiles s on s.trail_id = t.id and s.geometry_version = t.geometry_version
where t.state_code = 'WV'
order by t.name;

